#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>

const char* ssid = "ESP-Relay";
const char* password = "12345678";

ESP8266WebServer server(80);
const int relayPin = D1;
bool relayState = false;

void handleRoot() {
  String html = R"=====(
<!DOCTYPE html><html><head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ESP Relay</title>
<style>
body{font-family:Arial;text-align:center;background:#111;color:#fff;padding-top:40px}
.btn{display:inline-block;padding:20px 50px;font-size:24px;margin:20px;border:none;border-radius:12px;color:#fff}
.on{background:#00c853}.off{background:#d50000}
</style></head><body>
<h1>ESP Relay Control</h1>
<p>Status: <b>)=====";
  html += relayState ? "ON" : "OFF";
  html += R"=====(</b></p>
<a href="/on"><button class="btn on">ON</button></a>
<a href="/off"><button class="btn off">OFF</button></a>
</body></html>)=====";
  server.send(200, "text/html", html);
}

void handleOn() {
  digitalWrite(relayPin, HIGH);
  relayState = true;
  server.sendHeader("Location", "/");
  server.send(303);
}

void handleOff() {
  digitalWrite(relayPin, LOW);
  relayState = false;
  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
  Serial.begin(115200);
  WiFi.softAP(ssid, password);
  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
}

void loop() {
  server.handleClient();
}

#include <WiFi.h>
#include <WebServer.h>
#include <OneWire.h>
#include <DallasTemperature.h>

const char* ap_ssid = "ESP32-Temp";
const char* ap_pass = "12345678";
#define ONE_WIRE_BUS 4
#define RELAY1 5
#define RELAY2 6

OneWire oneWire(ONE_WIRE_BUS);
DallasTemperature sensors(&oneWire);
WebServer server(80);
bool r1 = false, r2 = false;

void applyRelays() {
  digitalWrite(RELAY1, r1 ? HIGH : LOW);
  digitalWrite(RELAY2, r2 ? HIGH : LOW);
}

void handleRoot() {
  sensors.requestTemperatures();
  float t = sensors.getTempCByIndex(0);
  String html = "<!DOCTYPE html><html><body style='background:#111;color:#fff;text-align:center;font-family:Arial'>";
  html += "<h2>ESP32 Temp</h2><p>" + String(t, 1) + " C</p>";
  html += "<p>R1:" + String(r1?"ON":"OFF") + " R2:" + String(r2?"ON":"OFF") + "</p>";
  html += "<p><a href='/r1on'>R1 ON</a> <a href='/r1off'>R1 OFF</a></p>";
  html += "<p><a href='/r2on'>R2 ON</a> <a href='/r2off'>R2 OFF</a></p></body></html>";
  server.send(200, "text/html", html);
}

void setup() {
  Serial.begin(115200);
  pinMode(RELAY1, OUTPUT);
  pinMode(RELAY2, OUTPUT);
  applyRelays();
  sensors.begin();
  WiFi.softAP(ap_ssid, ap_pass);
  Serial.println(WiFi.softAPIP());
  server.on("/", handleRoot);
  server.on("/r1on", []() { r1 = true; applyRelays(); server.sendHeader("Location", "/"); server.send(303); });
  server.on("/r1off", []() { r1 = false; applyRelays(); server.sendHeader("Location", "/"); server.send(303); });
  server.on("/r2on", []() { r2 = true; applyRelays(); server.sendHeader("Location", "/"); server.send(303); });
  server.on("/r2off", []() { r2 = false; applyRelays(); server.sendHeader("Location", "/"); server.send(303); });
  server.begin();
}

void loop() { server.handleClient(); }

